{"input_json_path": "polymorph_data/BN_polymorphs.json", "output_json_path": "consolidated_nitrides.json", "custom_code": "
import json
import glob

all_polymorphs = []

# Read all polymorph files
for file_path in glob.glob("polymorph_data/*_polymorphs.json"):
    try:
        with open(file_path, 'r') as f:
            file_data = json.load(f)
            if isinstance(file_data, list):
                all_polymorphs.extend(file_data)
    except Exception as e:
        print(f"Error reading {file_path}: {e}")

filtered_data = all_polymorphs
"}

